-- إصلاحُ الملخَّصات المبتورة.
-- وُلِّد آليًّا بـ scripts/repair-truncated-summaries.py: كلُّ حرفٍ مُضافٍ
-- منقولٌ بحرفه من حقل body الخاصِّ بالصفِّ نفسِه، لا من خارجه.
BEGIN;
UPDATE sharia_rulings SET summary = 'الأضحية: ذبح بهيمة الأنعام في أيام النحر تقرباً إلى الله. حكمها: سنة مؤكدة عند الجمهور، وواجبة عند الحنفية لمن يستطيع. شروطها: (1) أن تكون من الأنعام. (2) أن تبلغ السن: الإبل ٥ سنوات، البقر ٢، الضأن والمعز سنة…'
  WHERE id = 'bc669460-4b98-4417-bc40-a68359f81dfd';
UPDATE sharia_rulings SET summary = 'الحيض دم طبيعي يخرج من رحم المرأة السليمة. أحكامه: (1) تحريم الصلاة والصيام إلى أن تطهر (وتقضي الصيام لا الصلاة). (2) تحريم الطواف حول الكعبة. (3) تحريم الجماع. (4) يجوز لها قراءة القرآن (الأرجح عند كثير من المعاصرين) ومسّ المصحف محل خلاف…'
  WHERE id = 'beb97359-8e7c-4720-88ca-a264ca0af2fe';
UPDATE sharia_rulings SET summary = 'النسخ: رفع الحكم الشرعي الثابت بدليل متأخر. وفي القرآن ثلاثة أنواع: (1) نسخ التلاوة والحكم معاً — رُفع اللفظ والحكم، ومثاله ما رُوي في آيات الرجم. (2) نسخ التلاوة دون الحكم — رُفع اللفظ وبقي العمل بالحكم…'
  WHERE id = 'c05f1947-0001-48c1-93ac-44c54c9520e1';
UPDATE sharia_rulings SET summary = 'منهج أهل السنة: (1) الطاعة في المعروف. (2) الصبر على الجور مع عدم تأييده. (3) النصيحة للحاكم سراً لا علناً. (4) عدم الخروج ما لم يُرَ كفر بواح (ظاهر) عليه دليل من القرآن والسنة…'
  WHERE id = 'c22ac0eb-9d6d-4f3f-a906-121a611c4dff';
UPDATE sharia_rulings SET summary = 'الإسناد هو سلسلة الرواة التي تصل الحديث إلى النبي ﷺ. وأهميته: 1) يُمكّن من التحقق من صحة الحديث. 2) حماية الدين من الكذب والوضع. 3) معرفة العدالة والضبط في كل راوٍ…'
  WHERE id = 'c28bf94b-97bb-4201-a3e8-3bd093b25713';
UPDATE sharia_rulings SET summary = 'يجوز قراءة القرآن من الذاكرة بدون وضوء بالنسبة للمحدث حدثاً أصغر عند جمهور العلماء. أما لمس المصحف فيشترط له الطهارة من الحدث الأصغر عند جمهور الفقهاء لقوله تعالى: ﴿لَّا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ﴾ [الواقعة: ٧٩]، وهو قول مالك والشافعي وأحمد…'
  WHERE id = 'c4d55faf-1c6c-4cec-9e92-5d285fb21793';
UPDATE sharia_rulings SET summary = 'فرائض الوضوء ستة: (1) النية. (2) غسل الوجه. (3) غسل اليدين إلى المرفقين. (4) مسح الرأس. (5) غسل الرجلين إلى الكعبين. (6) الترتيب. نواقض الوضوء: (أ) الخارج من السبيلين…'
  WHERE id = 'c667e3c3-843c-44ee-b5e7-5da264daf1ff';
UPDATE sharia_rulings SET summary = 'في حجة الوداع أوصى النبي ﷺ بجملة وصايا منها: (1) حرمة الدماء والأموال والأعراض. (2) تحريم ربا الجاهلية. (3) حقوق المرأة: ''استوصوا بالنساء خيراً''. (4) التمسك بكتاب الله والسنة…'
  WHERE id = 'c6bf7a80-c598-44fa-b3a3-970d4cc60431';
UPDATE sharia_rulings SET summary = 'يجب الإيمان بجميع الأنبياء جملةً دون تفريق بين نبيٍّ وآخر. والقرآن ذكر 25 نبياً بأسمائهم. أما العدد الإجمالي فقد ورد في بعض الأحاديث «مائة وأربعة وعشرون ألف نبي» وهو حديث في سنده ضعف…'
  WHERE id = 'c8331d98-be37-4b5b-8aab-8bb2b2aa2bdd';
UPDATE sharia_rulings SET summary = 'الصبر لغةً: الحبس والكف. اصطلاحاً: حبس النفس عمّا تكره وتجلّده على ما تشق عليها. قال ابن القيم: الصبر ثلاثة أقسام: (1) الصبر على طاعة الله: وهو الامتثال لأوامره مع ما فيها من مشقة…'
  WHERE id = 'c89ce0fd-9cbb-49fb-b6a7-52057074bea5';
UPDATE sharia_rulings SET summary = 'السنن الرواتب اثنتا عشرة ركعة: 4 قبل الظهر وركعتان بعده، وركعتان بعد المغرب، وركعتان بعد العشاء، وركعتان قبل الفجر. قال النبي ﷺ: «من صلى اثنتي عشرة ركعة في يوم وليلة بُني له بيت في الجنة» — رواه مسلم.'
  WHERE id = 'c8c86c98-661e-42e6-a5fa-89d464c1684c';
UPDATE sharia_rulings SET summary = 'يوم عرفة التاسع من ذي الحجة هو يوم الحج الأكبر. أعماله: (1) الوقوف بعرفة من الزوال حتى غروب الشمس — ركن الحج الأعظم. (2) الإكثار من الدعاء والذكر والتلبية والاستغفار…'
  WHERE id = 'c8cd52d2-e2de-4f87-8341-61cb4ea84443';
UPDATE sharia_rulings SET summary = 'محظورات الإحرام تنقسم إلى: (1) ما فيه الفدية: لبس المخيط للرجل أو تغطية الرأس — فيه فدية: صيام ثلاثة أيام أو إطعام ستة مساكين أو ذبح شاة. (2) تقليم الأظافر وحلق الشعر — فيه فدية مثل السابق…'
  WHERE id = 'c9b12246-1f31-438f-b96f-9932f46553f6';
UPDATE sharia_rulings SET summary = 'المساجد التي بُنيت على القبور أو أُدخل فيها قبر لا تجوز الصلاة فيها لنهي النبي ﷺ عن البناء على القبور. أما المساجد التي لها قبور في الجوار دون أن تكون في صحن المسجد فالصلاة فيها جائزة…'
  WHERE id = 'cc23fc6b-1e7f-48a7-8c1f-1e3595d6e412';
UPDATE sharia_rulings SET summary = 'الإسناد هو سلسلة الرواة الذين نقلوا الحديث من النبي ﷺ حتى وصل للمصنِّف. وأهميته: (1) التثبت من صحة النسبة للنبي ﷺ. (2) تمييز الصحيح من الضعيف. (3) حفظ الدين من الدخيل والمكذوب…'
  WHERE id = 'd0c164bb-ed63-4b41-853c-bbff242c8c9f';
UPDATE sharia_rulings SET summary = 'عمر بن الخطاب بن نفيل القرشي. أسلم في السنة السادسة من البعثة بعد أن سمع القرآن من أخته فاطمة. كان قبل إسلامه من أشد الناس على المسلمين. بعد إسلامه: أعلنه علناً وطاف بالبيت…'
  WHERE id = 'd209ca92-6942-44e0-acca-ef55bcfef95d';
UPDATE sharia_rulings SET summary = 'المُفطِرات: ما يُبطل الصيام ويوجب القضاء فقط، كأكل أو شرب ناسياً عند من يرى أنه يوجب القضاء. المُفسِدات: ما يُبطل الصيام ويوجب القضاء، كالأكل والشرب عمداً، والجماع…'
  WHERE id = 'd537826d-2398-4485-9209-0466f2fd6565';
UPDATE sharia_rulings SET summary = 'نواقض الوضوء (الحدث الأصغر): (1) ما خرج من السبيلين (بول، غائط، ريح). (2) النوم المستغرق. (3) زوال العقل (إغماء، سُكر). (4) لمس الفرج باليد مباشرة عند الجمهور. (5) أكل لحم الإبل (عند الحنابلة)…'
  WHERE id = 'd5ecf716-1f39-4b55-a9e1-e9b96dafa128';
UPDATE sharia_rulings SET summary = 'قسّم ابن تيمية وابن القيم التوحيد إلى ثلاثة أقسام: (1) توحيد الربوبية: الإقرار بأن الله وحده هو الخالق الرازق المدبر، وهذا لم ينكره المشركون عموماً. (2) توحيد الألوهية (العبادة): إفراد الله بجميع أنواع العبادة من صلاة ودعاء وذبح ونذر ودعاء ومحبة وخوف ورجاء…'
  WHERE id = 'd73112ab-b7d3-4096-94b1-e29d098173ee';
UPDATE sharia_rulings SET summary = 'أهل الحل والعقد هم علماء وأعيان الأمة المؤهلون لاختيار الإمام وعزله والنظر في المصالح العامة. صفاتهم: العلم، والعدالة، والخبرة، والرأي. دورهم: (1) اختيار الإمام بالشورى وبيعته…'
  WHERE id = 'da02c8bc-80b3-4eb4-9c22-78cc8a5312ef';
UPDATE sharia_rulings SET summary = 'الصبر: حبس النفس عن الجزع وكفّ اللسان عن التشكي وكف الجوارح عن التسخط — وهو واجب. الرضا: قبول القلب للقضاء وعدم تمنّيه لو كان غيره — وهو مستحب. الشكر: استعمال نعم الله في طاعته بالقلب واللسان والجوارح — وهو أعلى المقامات…'
  WHERE id = 'dda840ef-38e5-4a92-bc12-03663877a902';
UPDATE sharia_rulings SET summary = 'اختلف العلماء المعاصرون؛ فذهب كثير من العلماء إلى عدم مشروعيته لأنه بدعة لم يفعلها النبي ﷺ ولا الصحابة والتابعون، وهو قول ابن باز وابن عثيمين والألباني. وذهب آخرون إلى جوازه إن خلا من المنكرات قياساً على شكر يوم الاثنين…'
  WHERE id = 'e0bb4b56-d705-4cd7-ad5d-7ee1a62e90c7';
UPDATE sharia_rulings SET summary = 'يُفرَّق بين أنواع العمل في البنوك الربوية: (1) العمل الذي يرتبط مباشرة بالربا (كاتب عقود القروض الربوية، المحاسب المحدد للفوائد) — هذا محرَّم لقوله ﷺ «لعن الله آكل الربا وموكله وكاتبه وشاهديه»…'
  WHERE id = 'e80c3364-a14f-4d70-8186-1858df5621c1';
UPDATE sharia_rulings SET summary = 'القرض: عقد تمليك شيء لمن يرد مثله دون زيادة. وشرطه: ألا يجرّ نفعاً للمُقرِض وإلا كان ربا. ومن أبرز صوره: قرض النقود. أما البيع: فهو مبادلة مال بمال بالتراضي مع تحقق شروطه…'
  WHERE id = 'e8e5581e-9f28-4a81-af7d-fb8dc7e0814b';
UPDATE sharia_rulings SET summary = 'التأمين التجاري المتعارف عليه محرَّم عند جمهور العلماء المعاصرين لاشتماله على الغرر الفاحش والربا. أما التأمين التكافلي (التعاوني): فهو مشروع في أصله لأنه يقوم على التبرع المتبادل بين المشتركين وليس على المعاوضة، فيتبرع المشتركون في صندوق مشترك يتكافلون من خلاله…'
  WHERE id = 'ed6a82b2-b94a-46cc-8a18-5e3ff63d7b7d';
UPDATE sharia_rulings SET summary = 'الكتب الستة (الصحاح الستة) هي: (1) صحيح البخاري. (2) صحيح مسلم. (3) سنن أبي داود. (4) سنن الترمذي (الجامع). (5) سنن النسائي. (6) سنن ابن ماجه. اشتهرت بهذا الاسم لأن المحدثين رأوا أن هذه الكتب تضم أوفى مجموعة حديثية متحققة الضبط والاستيعاب…'
  WHERE id = 'ef9ce206-ab37-4395-80db-eed3b9c1896e';
UPDATE sharia_rulings SET summary = 'نصاب الذهب: ٢٠ مثقالاً = ٨٥ غراماً من الذهب الخالص. نصاب الفضة: ٢٠٠ درهم = ٥٩٥ غراماً من الفضة الخالصة. ومقدار الزكاة: رُبع العشر (٢.٥%). شرط الحول: أن تمر سنة قمرية كاملة…'
  WHERE id = 'f01801db-275d-4a57-985f-f083521bd0de';
UPDATE sharia_rulings SET summary = 'نهى النبي ﷺ عن بناء المساجد على القبور وعن الصلاة إليها. فإذا كان القبر في قبلة المسجد أو محيطه فالصلاة فيه مكروهة أو محرمة على خلاف العلماء. والأصل أن المسجد يُبنى خالياً من القبور…'
  WHERE id = 'f04596f4-9245-479d-bf64-4882ea7875ff';
UPDATE sharia_rulings SET summary = 'الفائدة البنكية المُسبقة المحددة في القرض ربا محرم بإجماع الفقهاء لدخولها في حديث ''كل قرض جرّ نفعاً فهو ربا''. البديل الشرعي: (1) المضاربة: رب المال يُموِّل والعامل يعمل والربح مُقسَّم بنسبة…'
  WHERE id = 'f3651ad3-7997-4343-85fa-e78a3d55b98e';
UPDATE sharia_rulings SET summary = 'يوم الشك هو اليوم الثلاثون من شعبان إذا لم يُرَ الهلال ولم يكتمل العدد. والراجح عند جمهور العلماء تحريم صيامه احتياطاً إلا إن صادف عادة صيام كالاثنين والخميس. قال النبي ﷺ: «لا تقدموا رمضان بصوم يوم أو يومين».'
  WHERE id = 'f3c91d87-38f8-4e85-8b96-b1070d10a3ce';
UPDATE sharia_rulings SET summary = 'عند جمهور الفقهاء (المالكية والشافعية والحنابلة): الفرض والواجب مترادفان، كلاهما ما أمر به الشارع أمراً جازماً. أما الحنفية فيفرّقون: الفرض: ما ثبت بدليل قطعي (كصلوات الخمس)، وجحوده كفر…'
  WHERE id = 'f6084d5c-55ef-436f-bd32-a96312c7abfc';
UPDATE sharia_rulings SET summary = 'مناسك الحج مرتبة زمنياً: (1) ٨ ذي الحجة (يوم التروية): الإحرام والتوجه إلى منى. (2) ٩ ذي الحجة: الوقوف بعرفة (ركن الحج الأعظم) من الزوال إلى الغروب، ثم المبيت بمزدلفة…'
  WHERE id = 'f7d9732c-d3a9-4f9c-8a51-55ed2d1e9f37';
UPDATE sharia_rulings SET summary = '(1) الحديث المتواتر: ما رواه عدد كبير من الرواة في كل طبقة يستحيل تواطؤهم على الكذب. مثاله: حديث ''من كذب عليّ متعمداً فليتبوأ مقعده من النار''. يُفيد اليقين القطعي ويجب العمل به…'
  WHERE id = 'f7e67756-ac32-4de3-b0dc-ba908d069e29';
UPDATE sharia_rulings SET summary = 'الزكاة تجب على: 1) الذهب والفضة والعملات النقدية (نصابها 85 غراماً للذهب — 2.5%). 2) عروض التجارة (نصابها كالنقود — 2.5%). 3) الزروع والثمار (نصابها 5 أوسق — العُشر أو نصفه)…'
  WHERE id = 'f971b41d-810b-49f3-8ccd-c20d901d047b';
UPDATE sharia_rulings SET summary = 'أبو بكر عبد الله بن أبي قحافة أبرز مناقبه: (1) أول الرجال إسلاماً. (2) صاحب النبي ﷺ في الغار. (3) أنفق معظم ماله في سبيل الله وتحرير العبيد. (4) أول من جمع القرآن في مصحف واحد…'
  WHERE id = 'f9bfc641-ffa2-40c9-9118-fe1ff150a6e5';
UPDATE sharia_rulings SET summary = 'اختلف العلماء في الذكر الجماعي المنظّم (بصوت واحد بعد الصلوات مثلاً): (1) القول بالجواز: استدل بعض العلماء بعموم فضل الذكر وأن الأصل الإباحة، وأن الاجتماع على الذكر جاء في أحاديث كحديث ''لا يقعد قوم يذكرون الله...''…'
  WHERE id = 'f9cd5ac6-c28b-48bf-8c90-f850212c2578';
UPDATE sharia_rulings SET summary = 'أركان الإيمان الستة: 1) الإيمان بالله. 2) الإيمان بالملائكة. 3) الإيمان بالكتب. 4) الإيمان بالرسل. 5) الإيمان باليوم الآخر. 6) الإيمان بالقدر خيره وشره. الدليل القرآني: ﴿آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ﴾ [البقرة: ٢٨٥] (البقرة — 285)…'
  WHERE id = 'fd44a71a-0026-438a-8710-18609b243f6f';
UPDATE sharia_rulings SET summary = '(1) المرفوع: ما نُسب إلى النبي ﷺ قولاً أو فعلاً أو تقريراً أو صفة، سواء اتصل سنده أو انقطع. (2) الموقوف: ما نُسب إلى الصحابي فحسب من قول أو فعل، وقد يُحكم له بحكم المرفوع إن لم يكن للرأي فيه مجال…'
  WHERE id = 'fe11f1f8-1d27-4c8c-a443-8390d186e2c6';
COMMIT;
